 * `tags` are its tags, trimmed, lower-cased, without repeats and sorted (empty for none);
 * `comments` are its comments, oldest first, each "<user> on <date>: <text>" with the sheet's today when written;
 * `batch` is the number of the settle batch (a bulk settle) that settled it (null when none, or settled one at a time);
 * `reviewOn` (yyyy-mm-dd) is the sheet's today it last went to REVIEW (null when it never did);
 * `lines` are its lines, in the order added, each "<label> <qty> x <unit>" (a DRAFT's amount is then their sum);
 * `waived` is whether a steward waived its late charge: it bears none from then on;
 * `held` is whether it is held: it still counts in every total, as a held person's claims do;
 * `shares` are the people it is shared with, in the order added: each holds that percent of its due (see `personPart`);
 * `pendingOn` (yyyy-mm-dd) is the sheet's today it last went to PENDING (null when it never did);
 * `reviewUser` is the user a steward last assigned its review to (null when never), kept after it leaves REVIEW.
 */
export type Claim = {
  id: number;
  personId: number;
  amount: string;
  date: string;
  note: string;
  status: ClaimStatus;
  number: string | null;
  settledDue: string | null;
  openedBy: string | null;
  stated: boolean;
  statedDue: string | null;
  corrects: string | null;
  dueBy: string;
  log: string[];
  deferredUntil: string | null;
  proofs: number;
  proofsReceipt: number;
  proofsPhoto: number;
  splitFrom: string | null;
  lockedBy: string | null;
  lateEntry: boolean;
  remindedOn: string | null;
export const isDeferred = (c: Claim, today: string) =>
  c.status === 'OPEN' && c.deferredUntil !== null && (today === '' || today < c.deferredUntil);

/**
 * Only open (OPEN or PENDING) and SETTLED claims count toward claimed, due and every total; drafts, voided and
 * deleted ones do not, nor do a person's open claims once the sheet's `today` reaches their retirement date, unless a
 * statement bound them, nor an OPEN claim deferred on the sheet's `today`. A hold (the claim's or its person's) does
 * not leave a claim out of any total: it only takes the person's cut out of the pools.
 */
export const counts = (c: Claim, people: Person[], today: string) =>
  !isDeferred(c, today) &&
  (c.status === 'SETTLED' ||
  (isOpen(c) &&
    (c.stated || !leftOut(people.find((p) => p.id === c.personId), today))));

/** Whether the claim counts toward claimed: as `counts`. */
export const countsClaimed = (c: Claim, people: Person[], today: string) => counts(c, people, today);

/** Whether the person's unbound open claims are left out: retired by `today`. */
const leftOut = (person: Person | undefined, today: string) =>
  !!person?.retiredFrom && !!today && person.retiredFrom <= today;

/** The first day (yyyy-mm-dd) of the 30 days up to and including the sheet's `today`. */
const activeFrom = (today: string) => new Date(Date.parse(`${today}T00:00:00Z`) - 29 * 86_400_000).toISOString().slice(0, 10);

/**
 * Whether the person is active: they have an open (OPEN or PENDING) claim that counts, dated within the 30 days up to
 * and including the sheet's `today` (never while `today` is not loaded).
 */
export function isActive(personId: number, claims: Claim[], people: Person[], today: string): boolean {
  if (today === '') return false;
  const from = activeFrom(today);
  return claims.some(
    (c) => c.personId === personId && isOpen(c) && counts(c, people, today) && from <= c.date && c.date <= today,
  );
}

/** Under the sheet's key, so re-loading the sheet re-reads its claims. */
export const claimsKey = (sheetId: string) => [...sheetKey(sheetId), 'claims'] as const;

/** Under the claims' key, so whatever re-reads the claims re-reads the last settle batch too. */

